{"cards": [{"node_code": "N_0d403c6bdae3b237", "definition": "研究由刚性构件通过低副（转动副、移动副）连接而成的平面机构，涵盖四杆、曲柄滑块、导杆及多杆组合机构的运动学分析与综合设计。", "boundary": "聚焦于平面内通过铰链或滑动连接实现的运动传递与变换。包括机构类型判定、急回特性、死点位置分析、杆长条件及运动轨迹综合。不涉及高副（如凸轮接触）主导的机构，也不涉及空间运动或齿轮啮合传动。", "includes": ["四杆机构（曲柄摇杆、双曲柄、双摇杆）的结构分析与综合", "曲柄滑块、导杆机构的运动特性与尺寸设计", "多杆、组合及多环平面机构的运动学解算与优化"], "excludes": ["凸轮轮廓设计与高副接触力学（归凸轮与间歇运动机构节点）", "齿轮轮系的传动比计算与齿形设计（归齿轮与组合机构节点）"], "sibling_distinctions": [{"other_code": "N_3e5e156bf61c592e", "rule": "本节点主要处理低副（铰链/滑动）连接的连续运动机构；兄弟节点处理高副（凸轮）或特定几何形状（棘轮/槽轮）实现的间歇运动。"}, {"other_code": "N_28d2109c4f677b7f", "rule": "本节点侧重具体机构类型（如四杆、滑块）的结构实现；兄弟节点侧重通用的数学综合方法（如给定轨迹反求机构参数），可应用于本节点机构。"}], "cross_boundary_rule": "涉及平面机构综合时，若侧重具体构件连接形式与类型判定归本节点，若侧重通用轨迹/函数反求算法归轨迹、函数与运动规律综合节点。"}, {"node_code": "N_3e5e156bf61c592e", "definition": "研究利用凸轮轮廓或特定几何结构（棘轮、槽轮）实现从连续运动到间歇运动、停歇运动或特定分度动作的机构设计与原理。", "boundary": "聚焦于平面内实现间歇、分度或停歇功能的机构。涵盖盘形/圆柱凸轮轮廓设计、压力角与基圆选择；棘轮、槽轮机构的分度原理与运动特性。不涉及连续运动的连杆机构或齿轮传动。", "includes": ["盘形与圆柱凸轮机构的轮廓设计、运动规律及压力角分析", "棘轮、槽轮机构的分度原理、运动特性及结构形式", "实现停歇、间歇或步进动作的平面机构综合"], "excludes": ["连续运动的平面连杆机构设计（归平面连杆机构节点）", "空间分度机构或复杂多轴同步机构（归空间、柔顺与变胞机构或分度机构与定位装置节点）"], "sibling_distinctions": [{"other_code": "N_0d403c6bdae3b237", "rule": "本节点核心特征是“间歇”或“分度”运动，常涉及高副或特殊几何；兄弟节点核心特征是“连续”运动，主要涉及低副连接。"}, {"other_code": "N_28d2109c4f677b7f", "rule": "本节点侧重实现间歇/分度功能的具体机构形式（凸轮、棘轮）；兄弟节点侧重通用的运动规律综合方法，可作为本节点设计的数学工具。"}], "cross_boundary_rule": "涉及间歇运动设计时，若侧重凸轮轮廓或棘轮/槽轮结构归本节点，若侧重通用运动规律方程推导归轨迹、函数与运动规律综合节点。"}, {"node_code": "N_28d2109c4f677b7f", "definition": "研究基于给定运动轨迹、函数关系或运动规律，反求平面机构（连杆、凸轮等）几何参数与结构形式的通用综合理论与方法。", "boundary": "聚焦于机构设计的数学与几何综合方法，而非特定机构类型的结构细节。涵盖轨迹综合（如连杆机构轨迹生成）、函数综合（如凸轮运动规律设计）及运动规律综合。适用于平面连杆与凸轮机构的设计过程，提供从需求到参数的映射方法。", "includes": ["基于轨迹点的平面机构综合方法（如连杆机构轨迹设计）", "基于函数关系的机构综合（如凸轮运动规律与轮廓反求）", "基于运动规律（位移、速度、加速度）的机构参数优化与综合"], "excludes": ["具体机构（如四杆、凸轮）的结构类型判定与基本运动特性分析（归平面连杆或凸轮节点）", "空间机构的运动学综合（归空间、柔顺与变胞机构节点）"], "sibling_distinctions": [{"other_code": "N_0d403c6bdae3b237", "rule": "本节点提供通用的“综合方法”（如何从轨迹/函数得到参数）；兄弟节点关注“具体机构”（四杆、滑块）的结构与特性。"}, {"other_code": "N_3e5e156bf61c592e", "rule": "本节点提供通用的“综合方法”；兄弟节点关注实现间歇/分度功能的“具体机构”（凸轮、棘轮）。"}], "cross_boundary_rule": "涉及机构设计时，若侧重通用数学/几何综合算法（如轨迹反求、函数拟合）归本节点，若侧重特定机构（四杆、凸轮）的结构实现与特性分析归相应机构节点。"}]}
